  bool xinengMaxCatalogShowsRoleGroup(XinengMaxCatalogMode mode, int group) {
    if (mode == XinengMaxCatalogMode::All)
      return group >= 0 && group < kXinengSiteMaxRoleGroups;
    switch (group) {
      case 0:
      case 1:
        return mode == XinengMaxCatalogMode::Site;
      case 2:
        return mode == XinengMaxCatalogMode::Warehouse;
      case 3:
        return mode == XinengMaxCatalogMode::Power;
      case 4:
        return mode == XinengMaxCatalogMode::Safety;
      case 5:
        return mode == XinengMaxCatalogMode::Security;
      default:
        return false;
    }
  }

  bool xinengMaxCatalogShowsHeavyAsset(XinengMaxCatalogMode mode, int asset) {
    if (mode == XinengMaxCatalogMode::All)
      return asset >= 0 && asset < kXinengSiteMaxHeavyAssets;
    if (asset >= 0 && asset <= 4)
      return mode == XinengMaxCatalogMode::Site;
    if (asset == 5)
      return mode == XinengMaxCatalogMode::Power;
    if (asset == 6 || asset == 7)
      return mode == XinengMaxCatalogMode::Safety;
    if (asset == 8)
      return mode == XinengMaxCatalogMode::Warehouse;
    return false;
  }

  bool xinengMaxCatalogShowsFootprint(XinengMaxCatalogMode mode, int footprint) {
    if (mode == XinengMaxCatalogMode::All)
      return footprint >= 0 && footprint < kXinengSiteMaxCoverageFootprints;
    if (footprint >= 0 && footprint <= 3)
      return mode == XinengMaxCatalogMode::Site;
    if (footprint == 4 || footprint == 5)
      return mode == XinengMaxCatalogMode::Warehouse;
    if (footprint == 6)
      return mode == XinengMaxCatalogMode::Safety;
    if (footprint == 7)
      return mode == XinengMaxCatalogMode::Power || mode == XinengMaxCatalogMode::Security;
    return false;
  }

  bool xinengMaxCatalogShowsRiskLink(XinengMaxCatalogMode mode, int link) {
    if (mode == XinengMaxCatalogMode::All)
      return link >= 0 && link < kXinengSiteMaxRiskLinks;
    switch (link) {
      case 0:
        return mode == XinengMaxCatalogMode::Site || mode == XinengMaxCatalogMode::Safety;
      case 1:
        return mode == XinengMaxCatalogMode::Site;
      case 2:
        return mode == XinengMaxCatalogMode::Warehouse || mode == XinengMaxCatalogMode::Security;
      case 3:
        return mode == XinengMaxCatalogMode::Power;
      case 4:
        return mode == XinengMaxCatalogMode::Safety;
      case 5:
        return mode == XinengMaxCatalogMode::Safety || mode == XinengMaxCatalogMode::Security;
      default:
        return false;
    }
  }

  bool xinengMaxCatalogShowsAnchorBeacon(XinengMaxCatalogMode mode, int beacon) {
    if (mode == XinengMaxCatalogMode::All)
      return beacon >= 0 && beacon < kXinengSiteMaxAnchorBeacons;
    if (beacon >= 0 && beacon <= 5)
      return mode == XinengMaxCatalogMode::Site;
    if (beacon >= 6 && beacon <= 8)
      return mode == XinengMaxCatalogMode::Warehouse;
    if (beacon >= 9 && beacon <= 11)
      return mode == XinengMaxCatalogMode::Power;
    if (beacon >= 12 && beacon <= 15)
      return mode == XinengMaxCatalogMode::Safety;
    if (beacon >= 16 && beacon <= 18)
      return mode == XinengMaxCatalogMode::Security;
    return false;
  }

  template <typename Predicate> int countXinengMaxCatalogItems(int total, Predicate&& predicate) {
    int count = 0;
    for (int i = 0; i < total; ++i) {
      if (predicate(i))
        ++count;
    }
    return count;
  }

  int xinengMaxCatalogActiveRoleGroups(XinengMaxCatalogMode mode) {
    return countXinengMaxCatalogItems(kXinengSiteMaxRoleGroups,
                                      [mode](int i) { return xinengMaxCatalogShowsRoleGroup(mode, i); });
  }

  int xinengMaxCatalogActiveHeavyAssets(XinengMaxCatalogMode mode) {
    return countXinengMaxCatalogItems(kXinengSiteMaxHeavyAssets,
                                      [mode](int i) { return xinengMaxCatalogShowsHeavyAsset(mode, i); });
  }

  int xinengMaxCatalogActiveCoverageFootprints(XinengMaxCatalogMode mode) {
    return countXinengMaxCatalogItems(kXinengSiteMaxCoverageFootprints,
                                      [mode](int i) { return xinengMaxCatalogShowsFootprint(mode, i); });
  }

  int xinengMaxCatalogActiveRiskLinks(XinengMaxCatalogMode mode) {
    return countXinengMaxCatalogItems(kXinengSiteMaxRiskLinks,
                                      [mode](int i) { return xinengMaxCatalogShowsRiskLink(mode, i); });
  }

  int xinengMaxCatalogActiveAnchorBeacons(XinengMaxCatalogMode mode) {
    return countXinengMaxCatalogItems(kXinengSiteMaxAnchorBeacons,
                                      [mode](int i) { return xinengMaxCatalogShowsAnchorBeacon(mode, i); });
  }

  int xinengMaxCatalogActiveConversionStages(XinengMaxCatalogMode mode) {
    return mode == XinengMaxCatalogMode::All || xinengMaxCatalogActiveRoleGroups(mode) > 0
               ? kXinengSiteMaxConversionStages
               : 0;
  }

  bool powerMaxProxyShowsForCatalogMode(XinengMaxCatalogMode mode) {
    return mode == XinengMaxCatalogMode::All || mode == XinengMaxCatalogMode::Power;
  }

  bool securitySourceShowsForCatalogMode(XinengMaxCatalogMode mode) {
    return mode == XinengMaxCatalogMode::All || mode == XinengMaxCatalogMode::Security;
  }

