  struct Vertex {
    glm::vec3 position;
    glm::vec3 color;
    glm::vec3 normal;
    glm::vec2 uv;
    float kind = 0.0f; // 0 lit, 1 terrain, 2 unlit overlay, 3 fire/gas/smoke, 4 sky.
    // x: material-atlas tile (-1 = procedural/default), y: metallic,
    // z: perceptual roughness, w: 1 glTF/PBR, 2 base photo, 3 child photo, 4 context.
    glm::vec4 pbr = {-1.0f, 0.0f, 0.65f, 0.0f};

    static VertexInputBindingDescription binding() {
      VertexInputBindingDescription b;
      b.binding = 0;
      b.stride = sizeof(Vertex);
      b.perInstance = false;
      return b;
    }

    static std::vector<VertexInputAttributeDescription> attributes() {
      std::vector<VertexInputAttributeDescription> attrs(6);
      attrs[0] = {0, 0, Format::R32G32B32_SFLOAT, offsetof(Vertex, position)};
      attrs[1] = {1, 0, Format::R32G32B32_SFLOAT, offsetof(Vertex, color)};
      attrs[2] = {2, 0, Format::R32G32B32_SFLOAT, offsetof(Vertex, normal)};
      attrs[3] = {3, 0, Format::R32G32_SFLOAT, offsetof(Vertex, uv)};
      attrs[4] = {4, 0, Format::R32_SFLOAT, offsetof(Vertex, kind)};
      attrs[5] = {5, 0, Format::R32G32B32A32_SFLOAT, offsetof(Vertex, pbr)};
      return attrs;
    }
  };

