  float saturate(float value) {
    return glm::clamp(value, 0.0f, 1.0f);
  }

  float clampFloat(float value, float lo, float hi) {
    return glm::clamp(value, lo, hi);
  }

  float parseFloatValue(const std::string& arg, size_t prefixLength) {
    return std::stof(arg.substr(prefixLength));
  }

  int parseIntValue(const std::string& arg, size_t prefixLength) {
    return std::stoi(arg.substr(prefixLength));
  }

  float degreesFromRadians(float radians) {
    return radians * 180.0f / kPi;
  }

  glm::vec3 sunDirectionFromAngles(float azimuthDegrees, float elevationDegrees) {
    const float azimuth = glm::radians(azimuthDegrees);
    const float elevation = glm::radians(elevationDegrees);
    const float horizontal = std::cos(elevation);
    return glm::normalize(glm::vec3{
        std::cos(azimuth) * horizontal,
        std::sin(azimuth) * horizontal,
        std::sin(elevation),
    });
  }

  glm::vec2 sunAnglesFromDirection(glm::vec3 dir) {
    if (glm::length(dir) < 0.001f)
      return {214.8f, 56.1f};
    dir = glm::normalize(dir);
    float azimuth = degreesFromRadians(std::atan2(dir.y, dir.x));
    if (azimuth < 0.0f)
      azimuth += 360.0f;
    const float elevation = degreesFromRadians(std::asin(glm::clamp(dir.z, -1.0f, 1.0f)));
    return {azimuth, elevation};
  }

  void configureConsoleEncoding() {
#ifdef _WIN32
    SetConsoleOutputCP(CP_UTF8);
    SetConsoleCP(CP_UTF8);
#endif
  }

  glm::vec3 jsonVec3(const Json& value, glm::vec3 fallback) {
    if (!value.is_array() || value.size() < 3)
      return fallback;
    return {
        value.at(0).get<float>(),
        value.at(1).get<float>(),
        value.at(2).get<float>(),
    };
  }

  fs::path resolveProjectPath(const fs::path& relative) {
#ifdef _WIN32
    wchar_t executable[32768]{};
    if (GetModuleFileNameW(nullptr, executable, 32768)) {
      const auto portable = fs::path(executable).parent_path() / relative;
      if (fs::exists(portable))
        return portable;
    }
#endif
    if (fs::exists(relative))
      return relative;
#if defined(HT_SOURCE_ROOT) && !defined(HT_LANDSCAPE_EDITOR)
    const fs::path sourceRoot = fs::path(HT_SOURCE_ROOT) / relative;
    if (fs::exists(sourceRoot))
      return sourceRoot;
#endif
    return relative;
  }

  fs::path sceneConfigPath(const Cli& cli) {
    return resolveProjectPath(fs::path("data") / "showcase" / (cli.scene + ".scene.json"));
  }

  SceneConfig loadSceneConfig(const Cli& cli) {
    SceneConfig config;
    const fs::path path = sceneConfigPath(cli);
    config.path = path.generic_string();
    std::ifstream in(path, std::ios::binary);
    if (!in)
      return config;

    try {
      const Json doc = Json::parse(in);
      config.loaded = true;
      if (doc.contains("asset_root"))
        config.assetRoot = doc.at("asset_root").get<std::string>();

      if (doc.contains("terrain")) {
        const Json& terrain = doc.at("terrain");
        if (terrain.contains("fallback_bin"))
          config.terrain.fallbackBin = terrain.at("fallback_bin").get<std::string>();
        if (terrain.contains("bounds_m") && terrain.at("bounds_m").is_array() && terrain.at("bounds_m").size() >= 4) {
          config.terrain.minX = terrain.at("bounds_m").at(0).get<float>();
          config.terrain.minY = terrain.at("bounds_m").at(1).get<float>();
          config.terrain.maxX = terrain.at("bounds_m").at(2).get<float>();
          config.terrain.maxY = terrain.at("bounds_m").at(3).get<float>();
        }
        if (terrain.contains("grid") && terrain.at("grid").is_array() && terrain.at("grid").size() >= 2) {
          config.terrain.segmentsX = std::max(32, terrain.at("grid").at(0).get<int>());
          config.terrain.segmentsY = std::max(32, terrain.at("grid").at(1).get<int>());
        }
        if (cli.preset == Preset::Huilian) {
          if (terrain.contains("huilian_bin"))
            config.terrain.fallbackBin = terrain.at("huilian_bin").get<std::string>();
          if (terrain.contains("huilian_bounds_m") && terrain.at("huilian_bounds_m").is_array() &&
              terrain.at("huilian_bounds_m").size() >= 4) {
            config.terrain.minX = terrain.at("huilian_bounds_m").at(0).get<float>();
            config.terrain.minY = terrain.at("huilian_bounds_m").at(1).get<float>();
            config.terrain.maxX = terrain.at("huilian_bounds_m").at(2).get<float>();
            config.terrain.maxY = terrain.at("huilian_bounds_m").at(3).get<float>();
          }
          if (terrain.contains("huilian_grid") && terrain.at("huilian_grid").is_array() &&
              terrain.at("huilian_grid").size() >= 2) {
            config.terrain.segmentsX = std::max(32, terrain.at("huilian_grid").at(0).get<int>());
            config.terrain.segmentsY = std::max(32, terrain.at("huilian_grid").at(1).get<int>());
          }
        }
      }

      if (doc.contains("camera_presets") && doc.at("camera_presets").is_object()) {
        for (const auto& [name, camera] : doc.at("camera_presets").items()) {
          CameraPresetConfig preset;
          if (camera.contains("eye"))
            preset.eye = jsonVec3(camera.at("eye"), preset.eye);
          if (camera.contains("target"))
            preset.target = jsonVec3(camera.at("target"), preset.target);
          if (camera.contains("fov_deg"))
            preset.fovDeg = camera.at("fov_deg").get<float>();
          config.cameras[name] = preset;
        }
      }

      if (doc.contains("environment")) {
        const Json& env = doc.at("environment");
        if (env.contains("sun_dir")) {
          config.environment.sunDir = glm::normalize(jsonVec3(env.at("sun_dir"), config.environment.sunDir));
          config.environment.hasSun = true;
        }
        if (env.contains("sun_intensity"))
          config.environment.sunIntensity = env.at("sun_intensity").get<float>();
        if (env.contains("fog_density")) {
          config.environment.fog = saturate(env.at("fog_density").get<float>());
          config.environment.hasFog = true;
        }
        if (env.contains("cloud_amount")) {
          config.environment.cloud = clampFloat(env.at("cloud_amount").get<float>(), 0.0f, 2.0f);
          config.environment.hasCloud = true;
        }
        if (env.contains("rain_amount")) {
          config.environment.rain = saturate(env.at("rain_amount").get<float>());
          config.environment.hasRain = true;
        }
        if (env.contains("snow_amount")) {
          config.environment.snow = saturate(env.at("snow_amount").get<float>());
          config.environment.hasSnow = true;
        }
        if (env.contains("wind")) {
          const glm::vec3 wind = jsonVec3(env.at("wind"), {1.0f, 0.35f, 0.0f});
          config.environment.windDirDegrees = sunAnglesFromDirection({wind.x, wind.y, 0.0f}).x;
          config.environment.hasWind = true;
        }
        if (env.contains("wind_speed")) {
          config.environment.windSpeed = clampFloat(env.at("wind_speed").get<float>(), 0.0f, 30.0f);
          config.environment.hasWindSpeed = true;
        }
      }

      if (doc.contains("point_lights") && doc.at("point_lights").is_array()) {
        config.declaredPointLights = std::min<int>(16, static_cast<int>(doc.at("point_lights").size()));
      }
    } catch (const std::exception& exc) {
      std::cerr << "[showcase_demo] scene config parse failed: " << config.path << " - " << exc.what() << "\n";
      config.loaded = false;
    }
    return config;
  }

  const ZhumadianStageRuntime& zhumadianStageRuntime(const SceneConfig& config, bool childDetail, bool fullScene) {
    static std::array<ZhumadianStageRuntime, 3> runtimes;
    ZhumadianStageRuntime& runtime = runtimes[fullScene ? 2 : (childDetail ? 1 : 0)];
    if (runtime.attempted)
      return runtime;
    runtime.attempted = true;
    runtime.modelPath = resolveProjectPath(fs::path(config.assetRoot) / "zhumadian" /
                                           (fullScene ? "full" : (childDetail ? "child1" : "")) /
                                           (fullScene ? "zhumadian_full.gltf" : "zhumadian_roi18.gltf"));
    runtime.rootIds.assign(kZhumadianStageRootIds.begin(), kZhumadianStageRootIds.end());
    if (fullScene) {
      try {
        std::ifstream input(resolveProjectPath("data/showcase/zhumadian_full_stage_manifest.json"));
        nlohmann::json manifest;
        input >> manifest;
        runtime.rootIds.clear();
        for (const auto& root : manifest.at("source_roots")) {
          runtime.rootIds.push_back(root.at("tile_id").get<int>());
          runtime.sourceRootBytes += root.at("bytes").get<uint64_t>();
        }
        if (runtime.rootIds.empty() || runtime.rootIds.size() != manifest.at("root_count").get<size_t>())
          throw std::runtime_error("full-scene root coverage mismatch");
      } catch (const std::exception& error) {
        std::cerr << "[showcase_demo] full-scene manifest failed: " << error.what() << "\n";
        return runtime;
      }
    }
    if (!fs::exists(runtime.modelPath)) {
      std::cerr << "[showcase_demo] Zhumadian stage model is missing: " << runtime.modelPath.string() << "\n";
      return runtime;
    }

    hongtu::asset::GltfLoader loader;
    auto model = loader.load(runtime.modelPath.string());
    if (!model.has_value()) {
      std::cerr << "[showcase_demo] failed to load Zhumadian stage model: " << runtime.modelPath.string() << " - "
                << loader.lastError() << "\n";
      return runtime;
    }
    runtime.model = std::move(*model);
    for (const auto& primitive : runtime.model.meshes) {
      runtime.vertices += primitive.positions.size();
      runtime.triangles += !primitive.indices.empty() ? primitive.indices.size() / 3 : primitive.positions.size() / 3;
      const bool materialValid =
          primitive.material_id >= 0 && primitive.material_id < static_cast<int>(runtime.model.materials.size());
      int textureIndex = -1;
      if (materialValid)
        textureIndex = runtime.model.materials[static_cast<size_t>(primitive.material_id)].base_color_texture;
      const bool textureValid = textureIndex >= 0 && textureIndex < static_cast<int>(runtime.model.textures.size()) &&
                                !runtime.model.textures[static_cast<size_t>(textureIndex)].pixels.empty();
      const bool uvValid = primitive.uvs.size() == primitive.positions.size();
      if (textureValid && uvValid)
        ++runtime.texturedPrimitives;
      else
        ++runtime.untexturedPrimitives;
      for (const glm::vec3& position : primitive.positions) {
        runtime.boundsMin = glm::min(runtime.boundsMin, position);
        runtime.boundsMax = glm::max(runtime.boundsMax, position);
      }
    }
    runtime.loaded = !runtime.model.empty() && runtime.vertices > 0 && runtime.triangles > 0 &&
                     runtime.texturedPrimitives > 0 && runtime.untexturedPrimitives == 0;
    return runtime;
  }

  struct ZhumadianGeometryDetail {
    hongtu::asset::ModelData model;
    std::vector<std::pair<uint32_t, uint32_t>> spans;
    uint64_t triangles = 0;
    uint64_t removedTriangles = 0;
    size_t roots = 0;
    bool loaded = false;
  };

  const ZhumadianGeometryDetail& zhumadianGeometryDetailRuntime(bool requested, bool foreground = false) {
    static const ZhumadianGeometryDetail empty;
    if (!requested)
      return empty;
    static std::array<std::optional<ZhumadianGeometryDetail>, 2> cache;
    auto& detail = cache[foreground ? 1 : 0];
    if (detail)
      return *detail;
    detail = [foreground] {
      ZhumadianGeometryDetail out;
      try {
        const fs::path directory =
            resolveProjectPath(foreground ? "assets/showcase/runtime/zhumadian/geometry_foreground"
                                          : "assets/showcase/runtime/zhumadian/geometry_detail");
        if (!fs::exists(directory / "detail_atlas.jpg"))
          return out;
        nlohmann::json manifest;
        std::ifstream input(resolveProjectPath(foreground ? "data/showcase/zhumadian_geometry_foreground.json"
                                                          : "data/showcase/zhumadian_geometry_detail.json"));
        input >> manifest;
        if (manifest.at("base_root_count").get<int>() != 2346 ||
            manifest.at("base_indices").get<uint64_t>() != 3055617ull * 3)
          throw std::runtime_error("geometry detail base mismatch");
        for (const auto& root : manifest.at("replacements"))
          for (const auto& span : root.at("spans"))
            out.spans.emplace_back(span.at(0).get<uint32_t>(), span.at(1).get<uint32_t>());
        std::sort(out.spans.begin(), out.spans.end());
        uint64_t end = 0;
        for (const auto& [start, count] : out.spans) {
          if (start < end || start % 3 || count % 3 || uint64_t(start) + count > 3055617ull * 3)
            throw std::runtime_error("invalid geometry replacement spans");
          end = uint64_t(start) + count;
          out.removedTriangles += count / 3;
        }
        hongtu::asset::GltfLoader loader;
        auto model = loader.load((directory / "detail.gltf").string());
        if (!model)
          throw std::runtime_error(loader.lastError());
        out.model = std::move(*model);
        for (const auto& mesh : out.model.meshes) {
          if (mesh.positions.empty() || mesh.uvs.size() != mesh.positions.size() || mesh.indices.empty())
            throw std::runtime_error("incomplete child mesh");
          out.triangles += mesh.indices.size() / 3;
        }
        out.roots = manifest.at("replacements").size();
        out.loaded = out.roots > 0 && out.triangles == manifest.at("triangles").get<uint64_t>() &&
                     out.removedTriangles == manifest.at("removed_base_triangles").get<uint64_t>();
      } catch (const std::exception& error) {
        std::cerr << "[showcase_demo] geometry detail unavailable; retaining complete base: " << error.what() << "\n";
      }
      return out;
    }();
    return *detail;
  }

  float hash21(float x, float y) {
    const float h = std::sin(x * 127.1f + y * 311.7f) * 43758.5453f;
    return h - std::floor(h);
  }

  float valueNoise(float x, float y) {
    const float ix = std::floor(x);
    const float iy = std::floor(y);
    const float fx = x - ix;
    const float fy = y - iy;
    const float ux = fx * fx * (3.0f - 2.0f * fx);
    const float uy = fy * fy * (3.0f - 2.0f * fy);
    const float a = hash21(ix, iy);
    const float b = hash21(ix + 1.0f, iy);
    const float c = hash21(ix, iy + 1.0f);
    const float d = hash21(ix + 1.0f, iy + 1.0f);
    return glm::mix(glm::mix(a, b, ux), glm::mix(c, d, ux), uy);
  }

  float fbm(float x, float y) {
    float sum = 0.0f;
    float amplitude = 0.55f;
    float frequency = 1.0f;
    for (int i = 0; i < 5; ++i) {
      sum += (valueNoise(x * frequency, y * frequency) * 2.0f - 1.0f) * amplitude;
      frequency *= 2.03f;
      amplitude *= 0.48f;
    }
    return sum;
  }

  template <typename T> bool readBinary(std::ifstream& input, T& value) {
    input.read(reinterpret_cast<char*>(&value), sizeof(T));
    return static_cast<bool>(input);
  }

  struct ShowcaseTerrainAsset {
    bool attempted = false;
    bool loaded = false;
    uint32_t width = 0;
    uint32_t height = 0;
    float minX = -1.0f;
    float maxX = 1.0f;
    float minY = -1.0f;
    float maxY = 1.0f;
    float sceneMinX = -1600.0f;
    float sceneMaxX = 1600.0f;
    float sceneMinY = -1200.0f;
    float sceneMaxY = 1200.0f;
    float baseElevation = 0.0f;
    float centerHeight = 0.0f;
    float minHeight = 0.0f;
    float maxHeight = 0.0f;
    uint32_t pathCount = 0;
    std::string path;
    std::vector<float> heights;
    std::vector<uint8_t> colors;
  };

  ShowcaseTerrainAsset& showcaseTerrainAsset() {
    static ShowcaseTerrainAsset asset;
    return asset;
  }

  bool isBinhaiTerrainAsset(const ShowcaseTerrainAsset& asset) {
    return asset.path.find("20260729") != std::string::npos || asset.path.find("binhai_terrain") != std::string::npos;
  }

  bool isHuilianTerrainAsset(const ShowcaseTerrainAsset& asset) {
    return asset.path.find("huilian_dem_30m") != std::string::npos;
  }

  bool loadShowcaseTerrainAsset(const TerrainConfig& terrain) {
    auto& asset = showcaseTerrainAsset();
    asset.sceneMinX = terrain.minX;
    asset.sceneMaxX = terrain.maxX;
    asset.sceneMinY = terrain.minY;
    asset.sceneMaxY = terrain.maxY;
    if (asset.attempted)
      return asset.loaded;
    asset.attempted = true;

    std::vector<fs::path> candidates;
    if (!terrain.fallbackBin.empty())
      candidates.push_back(terrain.fallbackBin);
    candidates.push_back(fs::path("assets") / "badaling" / "badaling_terrain.bin");
    candidates.push_back(fs::path("..") / "assets" / "badaling" / "badaling_terrain.bin");
    candidates.push_back(fs::path("..") / ".." / ".." / ".." / "assets" / "badaling" / "badaling_terrain.bin");

    std::ifstream input;
    fs::path selected;
    for (const fs::path& candidate : candidates) {
      const fs::path resolved = resolveProjectPath(candidate);
      input.open(resolved, std::ios::binary);
      if (input) {
        selected = resolved;
        break;
      }
      input.clear();
    }
    if (!input)
      return false;

    char magic[8] = {};
    input.read(magic, sizeof(magic));
    if (std::memcmp(magic, "HTBDALNG", 8) != 0)
      return false;

    uint32_t version = 0;
    uint32_t wallCount = 0;
    if (!readBinary(input, version) || !readBinary(input, asset.width) || !readBinary(input, asset.height) ||
        !readBinary(input, wallCount)) {
      return false;
    }
    if (version < 2 || asset.width < 2 || asset.height < 2 || asset.width > 4096 || asset.height > 4096)
      return false;

    if (!readBinary(input, asset.minX) || !readBinary(input, asset.maxX) || !readBinary(input, asset.minY) ||
        !readBinary(input, asset.maxY) || !readBinary(input, asset.baseElevation)) {
      return false;
    }

    const size_t pixelCount = static_cast<size_t>(asset.width) * static_cast<size_t>(asset.height);
    asset.heights.resize(pixelCount);
    asset.colors.resize(pixelCount * 3);
    input.read(reinterpret_cast<char*>(asset.heights.data()),
               static_cast<std::streamsize>(asset.heights.size() * sizeof(float)));
    input.read(reinterpret_cast<char*>(asset.colors.data()), static_cast<std::streamsize>(asset.colors.size()));
    if (!input)
      return false;

    asset.minHeight = std::numeric_limits<float>::max();
    asset.maxHeight = std::numeric_limits<float>::lowest();
    for (float height : asset.heights) {
      asset.minHeight = std::min(asset.minHeight, height);
      asset.maxHeight = std::max(asset.maxHeight, height);
    }
    asset.centerHeight = asset.heights[static_cast<size_t>(asset.height / 2) * asset.width + asset.width / 2];
    asset.pathCount = wallCount;
    asset.path = selected.generic_string();
    asset.loaded = true;
    std::cout << "[showcase_demo] loaded DEM/DOM terrain package: " << asset.path << " (" << asset.width << "x"
              << asset.height << ", relief=" << (asset.maxHeight - asset.minHeight) << "m, wall paths=" << wallCount
              << ")\n";
    return true;
  }

  float terrainAssetU(float x) {
    const auto& asset = showcaseTerrainAsset();
    return glm::clamp((x - asset.sceneMinX) / std::max(asset.sceneMaxX - asset.sceneMinX, 0.001f), 0.0f, 1.0f);
  }

  float terrainAssetV(float y) {
    const auto& asset = showcaseTerrainAsset();
    return glm::clamp((y - asset.sceneMinY) / std::max(asset.sceneMaxY - asset.sceneMinY, 0.001f), 0.0f, 1.0f);
  }

  float sampleShowcaseTerrainHeight(float x, float y) {
    const auto& asset = showcaseTerrainAsset();
    if (!asset.loaded || asset.heights.empty())
      return 0.0f;
    const float fx = terrainAssetU(x) * static_cast<float>(asset.width - 1);
    const float fy = terrainAssetV(y) * static_cast<float>(asset.height - 1);
    const uint32_t x0 = static_cast<uint32_t>(std::floor(fx));
    const uint32_t y0 = static_cast<uint32_t>(std::floor(fy));
    const uint32_t x1 = std::min(x0 + 1, asset.width - 1);
    const uint32_t y1 = std::min(y0 + 1, asset.height - 1);
    const float tx = fx - static_cast<float>(x0);
    const float ty = fy - static_cast<float>(y0);
    const auto at = [&](uint32_t px, uint32_t py) {
      return asset.heights[static_cast<size_t>(py) * asset.width + px];
    };
    const float a = glm::mix(at(x0, y0), at(x1, y0), tx);
    const float b = glm::mix(at(x0, y1), at(x1, y1), tx);
    return glm::mix(a, b, ty);
  }

  glm::vec3 sampleShowcaseTerrainColor(float x, float y) {
    const auto& asset = showcaseTerrainAsset();
    if (!asset.loaded || asset.colors.empty())
      return {0.24f, 0.34f, 0.18f};
    const float fx = terrainAssetU(x) * static_cast<float>(asset.width - 1);
    const float fy = terrainAssetV(y) * static_cast<float>(asset.height - 1);
    const uint32_t x0 = static_cast<uint32_t>(std::floor(fx));
    const uint32_t y0 = static_cast<uint32_t>(std::floor(fy));
    const uint32_t x1 = std::min(x0 + 1, asset.width - 1);
    const uint32_t y1 = std::min(y0 + 1, asset.height - 1);
    const float tx = fx - static_cast<float>(x0);
    const float ty = fy - static_cast<float>(y0);
    const auto at = [&](uint32_t px, uint32_t py) {
      const size_t i = (static_cast<size_t>(py) * asset.width + px) * 3;
      return glm::vec3{
          static_cast<float>(asset.colors[i + 0]) / 255.0f,
          static_cast<float>(asset.colors[i + 1]) / 255.0f,
          static_cast<float>(asset.colors[i + 2]) / 255.0f,
      };
    };
    const glm::vec3 a = glm::mix(at(x0, y0), at(x1, y0), tx);
    const glm::vec3 b = glm::mix(at(x0, y1), at(x1, y1), tx);
    return glm::mix(a, b, ty);
  }

  std::vector<uint8_t> buildShowcaseMaterialAtlas(uint32_t width, uint32_t height) {
    std::vector<uint8_t> rgba(static_cast<size_t>(width) * height * 4, 255);
    const uint32_t tileWidth = width / kShowcaseMaterialAtlasTiles;
    const auto toByte = [](float v) {
      return static_cast<uint8_t>(glm::clamp(v, 0.0f, 1.0f) * 255.0f + 0.5f);
    };
    for (uint32_t y = 0; y < height; ++y) {
      for (uint32_t x = 0; x < width; ++x) {
        const uint32_t tile = std::min<uint32_t>(kShowcaseMaterialAtlasTiles - 1, x / std::max<uint32_t>(1, tileWidth));
        const float u = static_cast<float>(x % std::max<uint32_t>(1, tileWidth)) / static_cast<float>(tileWidth);
        const float v = static_cast<float>(y) / static_cast<float>(height);
        const float grain = valueNoise(static_cast<float>(x) * 0.17f, static_cast<float>(y) * 0.17f);
        const float fine = hash21(static_cast<float>(x), static_cast<float>(y));
        glm::vec3 color{1.0f};
        if (tile == 0) {
          const float grass = valueNoise(u * 9.0f, v * 9.0f);
          color = glm::mix(glm::vec3{0.24f, 0.34f, 0.18f}, glm::vec3{0.42f, 0.48f, 0.26f}, grass);
          color = glm::mix(color, glm::vec3{0.38f, 0.34f, 0.25f}, glm::smoothstep(0.70f, 0.92f, grain) * 0.55f);
        } else if (tile == 1) {
          const float aggregate = glm::smoothstep(0.72f, 0.98f, fine);
          color = glm::vec3{0.105f, 0.112f, 0.118f} * glm::mix(0.72f, 1.35f, grain);
          color += glm::vec3{0.030f, 0.030f, 0.028f} * aggregate;
        } else if (tile == 2) {
          const float panelX = glm::smoothstep(0.018f, 0.0f, std::abs(std::fmod(u * 8.0f, 1.0f) - 0.5f));
          const float panelY = glm::smoothstep(0.018f, 0.0f, std::abs(std::fmod(v * 5.0f, 1.0f) - 0.5f));
          color = glm::vec3{0.54f, 0.55f, 0.52f} * glm::mix(0.86f, 1.12f, grain);
          color *= glm::mix(1.0f, 0.72f, std::max(panelX, panelY));
        } else if (tile == 3) {
          const float ribs = glm::smoothstep(0.82f, 1.0f, std::abs(std::fmod(u * 18.0f, 1.0f) - 0.5f) * 2.0f);
          color = glm::vec3{0.42f, 0.47f, 0.49f} * glm::mix(0.82f, 1.22f, grain);
          color += glm::vec3{0.10f, 0.12f, 0.12f} * ribs;
        } else if (tile == 4) {
          const float bolts = glm::smoothstep(0.82f, 0.96f, fine);
          color = glm::vec3{0.055f, 0.18f, 0.12f} * glm::mix(0.72f, 1.24f, grain);
          color += glm::vec3{0.16f, 0.21f, 0.18f} * bolts;
        } else {
          const float wear = valueNoise(u * 18.0f + 3.0f, v * 18.0f - 7.0f);
          color = glm::vec3{0.38f, 0.49f, 0.57f} * glm::mix(0.78f, 1.16f, grain);
          color = glm::mix(color, glm::vec3{0.20f, 0.24f, 0.27f}, glm::smoothstep(0.76f, 0.94f, wear) * 0.36f);
        }
        const size_t i = (static_cast<size_t>(y) * width + x) * 4;
        rgba[i + 0] = toByte(color.r);
        rgba[i + 1] = toByte(color.g);
        rgba[i + 2] = toByte(color.b);
        rgba[i + 3] = 255;
      }
    }
    return rgba;
  }

  bool loadRgbaImage(const fs::path& path, LoadedRgbaImage& out) {
    const std::string filename = path.string();
    int width = 0;
    int height = 0;
    int components = 0;
    unsigned char* pixels = stbi_load(filename.c_str(), &width, &height, &components, 4);
    if (!pixels || width <= 0 || height <= 0) {
      if (pixels)
        stbi_image_free(pixels);
      return false;
    }
    out.width = width;
    out.height = height;
    out.rgba.assign(pixels, pixels + static_cast<size_t>(width) * height * 4);
    stbi_image_free(pixels);
    return true;
  }

