      addPaintedRect(mesh, {x, -86.0f}, {7.2f, 0.24f}, yellow);
    addPaintedRect(mesh, {0.0f, -96.6f}, {302.0f, 0.16f}, warmWhite);
    addPaintedRect(mesh, {0.0f, -75.4f}, {302.0f, 0.16f}, warmWhite);

    for (float x = -218.0f; x <= 236.0f; x += 30.0f)
      addPaintedRect(mesh, {x, 92.0f}, {5.8f, 0.20f}, yellow);
    addPaintedRect(mesh, {10.0f, 84.3f}, {235.0f, 0.15f}, warmWhite);
    addPaintedRect(mesh, {10.0f, 99.7f}, {235.0f, 0.15f}, warmWhite);

    for (float y = -132.0f; y <= 132.0f; y += 28.0f)
      addPaintedRect(mesh, {-38.0f, y}, {0.22f, 5.6f}, yellow);
    addPaintedRect(mesh, {-46.1f, 0.0f}, {0.15f, 145.0f}, warmWhite);
