  SceneSettings applyXinengMaxCatalogCameraFocus(const Cli& cli, SceneSettings settings) {
    if (cli.preset == Preset::Models && cli.xinengMaxCatalogMode == XinengMaxCatalogMode::Power) {
      settings.eye = {92.0f, -330.0f, 136.0f};
      settings.target = {226.0f, -134.0f, 42.0f};
      settings.fovDeg = 39.0f;
      settings.fog = std::min(settings.fog, 0.040f);
    }
    return settings;
  }

  SceneSettings applyCliOverrides(const Cli& cli, SceneSettings settings) {
    if (cli.meshShadowProbe) {
      settings.eye = {0.0f, -8.0f, 32.0f};
      settings.target = {0.0f, 0.0f, 0.0f};
      settings.fovDeg = 44.0f;
      settings.sunAzimuthDegrees = 135.0f;
      settings.sunElevationDegrees = 45.0f;
      settings.sunDir = sunDirectionFromAngles(135.0f, 45.0f);
      settings.sunIntensity = 1.25f;
      settings.pointLights = 0;
      settings.rain = settings.snow = settings.fog = settings.cloud = 0.0f;
      settings.clear = {0.0f, 0.0f, 0.0f};
    }
    if (cli.preset == Preset::Huilian && cli.huilianView == "valve") {
      settings.eye = {756.0f, 488.0f, terrainHeight(756.0f, 488.0f) + 10.5f};
      settings.target = {780.0f, 527.0f, terrainHeight(780.0f, 527.0f) + 2.0f};
      settings.fovDeg = 42.0f;
      settings.fog = 0.0f;
      settings.cloud = 0.0f;
    } else if (cli.preset == Preset::Huilian && cli.huilianView == "dom-inspect") {
      settings.eye = {780.0f, 0.0f, terrainHeight(780.0f, 0.0f) + cli.huilianDomInspectionHeight};
      settings.target = {780.0f, 900.0f, terrainHeight(780.0f, 900.0f)};
      settings.fovDeg = 50.0f;
      settings.fog = settings.cloud = settings.particleIntensity = 0.0f;
    } else if (cli.preset == Preset::Huilian && cli.huilianView == "southwest") {
      settings.eye = {-5000.0f, -3000.0f, terrainHeight(-5000.0f, -3000.0f) + 100.0f};
      settings.target = {-4700.0f, -2650.0f, terrainHeight(-4700.0f, -2650.0f) + 18.0f};
      settings.fovDeg = 45.0f;
    } else if (cli.preset == Preset::Huilian && cli.huilianView == "overview") {
      settings.eye = {0.0f, 0.0f, terrainHeight(0.0f, 0.0f) + 900.0f};
      settings.target = {0.0f, 720.0f, terrainHeight(0.0f, 720.0f) + 20.0f};
      settings.fovDeg = 60.0f;
    } else if (cli.preset == Preset::Huilian && cli.huilianView == "dlg") {
      settings.eye = {0.0f, 0.0f, terrainHeight(0.0f, 0.0f) + 900.0f};
      settings.target = {0.0f, 720.0f, terrainHeight(0.0f, 720.0f) + 20.0f};
      settings.fovDeg = 60.0f;
      settings.fog = 0.0f;
      settings.cloud = 0.0f;
    } else if (cli.preset == Preset::Huilian && cli.huilianView == "approach") {
      const auto sample = huilianGlobalLocalSample(cli.huilianApproachProgress);
      settings.eye = glm::vec3(sample.camera_enu_m);
      settings.target = glm::vec3(sample.target_enu_m);
      settings.fovDeg = static_cast<float>(sample.vertical_fov_deg);
      settings.fog = 0.0f;
      settings.cloud = 0.0f;
      settings.particleIntensity = 0.0f;
      settings.clear = glm::mix(
          glm::vec3{0.004f, 0.009f, 0.022f}, glm::vec3{0.48f, 0.62f, 0.78f}, static_cast<float>(sample.local_blend));
    }
    if (cli.preset == Preset::Zhumadian) {
      if (cli.zhumadianFullScene) {
        const auto& runtime = zhumadianStageRuntime(SceneConfig{}, false, true);
        if (!runtime.loaded)
          throw std::runtime_error("Full Zhumadian scene unavailable; rebuild full-stage assets");
        const glm::vec3 center = (runtime.boundsMin + runtime.boundsMax) * 0.5f;
        const float radius = glm::length(runtime.boundsMax - runtime.boundsMin) * 0.5f;
        settings.target = center;
        settings.fovDeg = 54.0f;
        // A bounding sphere fits all eight corners, with margin at the default landscape aspect ratio.
        if (cli.zhumadianView == "plant") {
          settings.target = {500.0f, -1600.0f, 45.0f};
          settings.eye = {0.0f, -2050.0f, 430.0f};
          settings.fovDeg = 50.0f;
        } else if (cli.zhumadianNativeTile > 0 && cli.zhumadianView == "close") {
          nlohmann::json hierarchy;
          std::ifstream input(resolveProjectPath("data/showcase/zhumadian_native_hierarchy.json"));
          input >> hierarchy;
          const auto& root = hierarchy.at("root_records").at(cli.zhumadianNativeTile - 1);
          for (int axis = 0; axis < 3; ++axis)
            settings.target[axis] =
                (root.at("bounds_min").at(axis).get<float>() + root.at("bounds_max").at(axis).get<float>()) * 0.5f;
          settings.eye = settings.target + glm::vec3(-cli.zhumadianNativeHeight * 0.55f,
                                                     -cli.zhumadianNativeHeight * 0.6f,
                                                     cli.zhumadianNativeHeight);
          settings.fovDeg = 50;
        } else if (cli.zhumadianView == "boundary") {
          settings.target = {250.0f, -1450.0f, 27.0f};
          settings.eye = {-450.0f, -1450.0f, 65.0f};
          settings.fovDeg = 55.0f;
        } else if (cli.zhumadianView == "edge") {
          settings.target = {-250.0f, -1450.0f, 27.0f};
          settings.eye = {-1000.0f, -1450.0f, 160.0f};
          settings.fovDeg = 55.0f;
        } else if (cli.zhumadianView == "close") {
          settings.target = {929.0f, 650.0f, 42.0f};
          settings.eye = {700.0f, 400.0f, 360.0f};
        } else {
          const glm::vec3 direction =
              cli.zhumadianView == "oblique" ? glm::vec3{-0.8f, -1.0f, 0.8f} : glm::vec3{-0.28f, -0.45f, 1.4f};
          settings.eye = center + glm::normalize(direction) * (radius / std::sin(glm::radians(27.0f)) * 1.12f);
        }
      } else if (cli.zhumadianView == "oblique") {
        settings.eye = {650.0f, 365.0f, 245.0f};
        settings.target = {929.0f, 650.0f, 42.0f};
        settings.fovDeg = 48.0f;
      } else if (cli.zhumadianView == "close") {
        settings.eye = {842.0f, 542.0f, 110.0f};
        settings.target = {922.0f, 650.0f, 45.0f};
        settings.fovDeg = 55.0f;
      } else {
        settings.eye = {700.0f, 400.0f, 360.0f};
        settings.target = {929.0f, 650.0f, 42.0f};
        settings.fovDeg = 54.0f;
      }
    }
    if (cli.preset == Preset::Gis && cli.gisMeasureMode == GisMeasureMode::Volume) {
      const glm::vec2 focus = gisVolumeMeasureCenter2D();
      settings.eye = {-1080.0f, -980.0f, terrainHeight(-1080.0f, -980.0f) + 330.0f};
      settings.target = {focus.x, focus.y, static_cast<float>(gisVolumeReferenceElevationMeters())};
      settings.fovDeg = 48.0f;
    }
    if (cli.hasSunAzimuth || cli.hasSunElevation) {
      settings.sunAzimuthDegrees = cli.hasSunAzimuth ? cli.sunAzimuthDegrees : settings.sunAzimuthDegrees;
      settings.sunElevationDegrees = cli.hasSunElevation ? cli.sunElevationDegrees : settings.sunElevationDegrees;
      settings.sunDir = sunDirectionFromAngles(settings.sunAzimuthDegrees, settings.sunElevationDegrees);
    }
    if (cli.hasPointLights)
      settings.pointLights = glm::clamp(cli.pointLights, 0, 16);
    if (cli.hasWindDir)
      settings.windDirDegrees = cli.windDirDegrees;
    if (cli.hasWindSpeed)
      settings.windSpeed = clampFloat(cli.windSpeed, 0.0f, 30.0f);
    if (cli.hasRain)
      settings.rain = saturate(cli.rain);
    if (cli.hasSnow)
      settings.snow = saturate(cli.snow);
    if (cli.hasFog)
      settings.fog = saturate(cli.fog);
    if (cli.hasClouds)
      settings.cloud = clampFloat(cli.clouds, 0.0f, 2.0f);
    if (cli.hasParticleIntensity)
      settings.particleIntensity = clampFloat(cli.particleIntensity, 0.0f, 3.0f);
    return settings;
  }

  void addLowMarkerDisc(Mesh& mesh, glm::vec2 center, float radius, glm::vec3 color, float kind = 2.0f) {
    const float z = groundZ(center.x, center.y, 0.02f);
    addCylinder(mesh, {center.x, center.y, z - 0.05f}, radius, 0.08f, 20, color, kind);
  }

  void addLowGroundVectorMarker(
      Mesh& mesh, glm::vec2 origin, glm::vec2 direction, float length, glm::vec3 color, float kind = 2.0f) {
    if (glm::length(direction) < 0.001f)
      return;
    const glm::vec2 dir = glm::normalize(direction);
    const float angle = std::atan2(dir.y, dir.x);
    const glm::vec2 center = origin + dir * (length * 0.5f);
    addOrientedGroundRect(mesh, center, {length * 0.5f, 0.46f}, angle, color, 0.38f, kind);
    addOrientedGroundRect(mesh, origin + dir * length, {2.0f, 0.86f}, angle, color * 1.12f, 0.40f, kind);
  }

  void addInteractionMarkers(Mesh& mesh, const SceneSettings& settings) {
    const float windAngle = glm::radians(settings.windDirDegrees);
    const glm::vec3 windDir = {std::cos(windAngle), std::sin(windAngle), 0.0f};
    const glm::vec3 windOrigin = {92.0f, 30.0f, groundZ(92.0f, 30.0f, 5.6f)};
    addLowGroundVectorMarker(mesh,
                             {windOrigin.x, windOrigin.y},
                             {windDir.x, windDir.y},
                             18.0f + settings.windSpeed * 1.2f,
                             glm::vec3{0.050f, 0.235f, 0.265f},
                             2.0f);

    const glm::vec3 sunFlat = glm::normalize(glm::vec3{settings.sunDir.x, settings.sunDir.y, 0.0f});
    const glm::vec2 sunOrigin = {-292.0f, 156.0f};
    addLowMarkerDisc(mesh, sunOrigin, 4.0f, {0.18f, 0.145f, 0.065f}, 2.0f);
    addLowGroundVectorMarker(mesh, sunOrigin, {sunFlat.x, sunFlat.y}, 17.0f, glm::vec3{0.30f, 0.21f, 0.075f}, 2.0f);

    const glm::vec3 gas = {92.0f, 30.0f, groundZ(92.0f, 30.0f, 0.0f)};
    addLowMarkerDisc(mesh, {gas.x, gas.y}, 3.6f, {0.070f, 0.180f, 0.105f}, 2.22f);
    addEllipsoid(mesh, gas + glm::vec3{0.0f, 0.0f, 0.72f}, {1.55f, 1.55f, 0.30f}, {0.13f, 0.30f, 0.13f}, 4, 10, 2.22f);

    const glm::vec3 poolFire = {126.0f, -18.0f, groundZ(126.0f, -18.0f, 0.0f)};
    addLowMarkerDisc(mesh, {poolFire.x, poolFire.y}, 3.9f, {0.205f, 0.055f, 0.020f}, 2.22f);
    addEllipsoid(
        mesh, poolFire + glm::vec3{0.0f, 0.0f, 0.76f}, {1.65f, 1.65f, 0.32f}, {0.34f, 0.095f, 0.030f}, 4, 10, 2.22f);

    const glm::vec3 jetFire = {154.0f, -42.0f, groundZ(154.0f, -42.0f, 17.0f)};
    addLowGroundVectorMarker(
        mesh, {jetFire.x, jetFire.y}, {1.0f, 0.15f}, 13.5f, glm::vec3{0.24f, 0.070f, 0.025f}, 2.22f);
  }

  template <size_t N> float polylineLength2D(const std::array<glm::vec2, N>& points) {
    float length = 0.0f;
    for (size_t i = 0; i + 1 < N; ++i) {
      length += glm::length(points[i + 1] - points[i]);
    }
    return length;
  }

  template <size_t N> glm::vec2 samplePolyline2D(const std::array<glm::vec2, N>& points, float fraction) {
    if constexpr (N == 0) {
      return {0.0f, 0.0f};
    } else if constexpr (N == 1) {
      return points[0];
    } else {
      const float totalLength = polylineLength2D(points);
      if (totalLength <= 0.001f)
        return points[0];
      const float target = saturate(fraction) * totalLength;
      float accumulated = 0.0f;
      for (size_t i = 0; i + 1 < N; ++i) {
        const glm::vec2 a = points[i];
        const glm::vec2 b = points[i + 1];
        const float segmentLength = glm::length(b - a);
        if (segmentLength <= 0.001f)
          continue;
        if (target <= accumulated + segmentLength) {
          return glm::mix(a, b, saturate((target - accumulated) / segmentLength));
        }
        accumulated += segmentLength;
      }
      return points[N - 1];
    }
  }

  template <size_t N> float polygonArea2D(const std::array<glm::vec2, N>& points) {
    float sum = 0.0f;
    for (size_t i = 0; i < N; ++i) {
      const glm::vec2 a = points[i];
      const glm::vec2 b = points[(i + 1) % N];
      sum += a.x * b.y - b.x * a.y;
    }
    return std::abs(sum) * 0.5f;
  }

