  const std::array<glm::vec2, kOperationalProcessFlowOrthogonalPathPoints>& processFlowOrthogonalPath2D() {
    static const std::array<glm::vec2, kOperationalProcessFlowOrthogonalPathPoints> points = [] {
      std::array<glm::vec2, kOperationalProcessFlowOrthogonalPathPoints> folded{};
      const auto& nodes = processFlowPath2D();
      size_t out = 0;
      folded[out++] = nodes[0];
      for (int i = 0; i + 1 < kOperationalProcessFlowNodes; ++i) {
        const glm::vec2 a = nodes[static_cast<size_t>(i)];
        const glm::vec2 b = nodes[static_cast<size_t>(i + 1)];
        const bool xFirst = i % 2 == 0;
        folded[out++] = xFirst ? glm::vec2{b.x, a.y} : glm::vec2{a.x, b.y};
        folded[out++] = b;
      }
      return folded;
    }();
    return points;
  }

