  std::array<glm::vec2, kGisMeasurementVolumeVertices> gisVolumeMeasurePolygon2D() {
    if (isHuilianTerrainAsset(showcaseTerrainAsset())) {
      return {{
          glm::vec2{-4860.0f, -2800.0f},
          glm::vec2{-4520.0f, -2800.0f},
          glm::vec2{-4480.0f, -2520.0f},
          glm::vec2{-4820.0f, -2480.0f},
      }};
    }
    return {{
        glm::vec2{-760.0f, -650.0f},
        glm::vec2{-320.0f, -620.0f},
        glm::vec2{-350.0f, -280.0f},
        glm::vec2{-790.0f, -310.0f},
    }};
  }

  glm::vec2 gisVolumeMeasureCenter2D() {
    glm::vec2 center(0.0f);
    for (glm::vec2 point : gisVolumeMeasurePolygon2D())
      center += point;
    return center / static_cast<float>(kGisMeasurementVolumeVertices);
  }

  double gisVolumeReferenceElevationMeters() {
    double elevation = 0.0;
    for (glm::vec2 point : gisVolumeMeasurePolygon2D())
      elevation += static_cast<double>(terrainHeight(point.x, point.y));
    return elevation / static_cast<double>(kGisMeasurementVolumeVertices);
  }

  double gisVolumeSampleSpacingMeters() {
    return isHuilianTerrainAsset(showcaseTerrainAsset()) ? 30.0 : 12.0;
  }

  hongtu::measure::TerrainVolumeResult gisTerrainVolumeMeasurement() {
    const auto footprint_points = gisVolumeMeasurePolygon2D();
    std::vector<glm::dvec2> footprint;
    footprint.reserve(footprint_points.size());
    for (glm::vec2 point : footprint_points)
      footprint.emplace_back(point.x, point.y);
    hongtu::measure::TerrainVolumeOptions options;
    options.reference_elevation_m = gisVolumeReferenceElevationMeters();
    options.sample_spacing_m = gisVolumeSampleSpacingMeters();
    options.maximum_cells = 100000;
    return hongtu::measure::computeTerrainVolume(footprint, options, [](double x, double y) {
      return static_cast<double>(terrainHeight(static_cast<float>(x), static_cast<float>(y)));
    });
  }

  glm::dvec2 gisVolumeWgs84CenterLonLat() {
    const glm::vec2 center = gisVolumeMeasureCenter2D();
    const double u = std::clamp(static_cast<double>(terrainAssetU(center.x)), 0.0, 1.0);
    const double v = std::clamp(static_cast<double>(terrainAssetV(center.y)), 0.0, 1.0);
    if (!isHuilianTerrainAsset(showcaseTerrainAsset())) {
      constexpr double kWebMercatorRadiusM = 6378137.0;
      constexpr double kDegreesPerRadian = 180.0 / 3.14159265358979323846;
      const double mercator_x = std::lerp(kBinhaiMercatorMinX, kBinhaiMercatorMaxX, u);
      const double mercator_y = std::lerp(kBinhaiMercatorMinY, kBinhaiMercatorMaxY, v);
      const double longitude = mercator_x / kWebMercatorRadiusM * kDegreesPerRadian;
      const double latitude =
          (2.0 * std::atan(std::exp(mercator_y / kWebMercatorRadiusM)) - 3.14159265358979323846 * 0.5) *
          kDegreesPerRadian;
      return {longitude, latitude};
    }
    return {
        std::lerp(kHuilianWgs84WestLonDeg, kHuilianWgs84EastLonDeg, u),
        std::lerp(kHuilianWgs84SouthLatDeg, kHuilianWgs84NorthLatDeg, v),
    };
  }

