  void addMaxEmergencyFireWaterMonitorProxy(Mesh& mesh, glm::vec2 c, glm::vec2 target2, const SceneSettings& settings) {
    const float z = groundZ(c.x, c.y, 0.0f);
    const glm::vec2 aim2 = glm::normalize(target2 - c);
    const glm::vec3 aim = {aim2.x, aim2.y, 0.0f};
    const glm::vec3 red = {0.55f, 0.065f, 0.032f};
    const glm::vec3 dark = {0.18f, 0.045f, 0.028f};
    const glm::vec3 water = {0.16f, 0.44f, 0.64f};
    const float windAngle = glm::radians(settings.windDirDegrees);
    const glm::vec2 wind = {std::cos(windAngle), std::sin(windAngle)};
    const float windDrift = clampFloat(settings.windSpeed, 0.0f, 18.0f) * 0.26f;

    addEquipmentShadow(mesh, c, {5.4f, 4.8f}, 7.4f, settings.sunDir, 0.22f);
    addLowMarkerDisc(mesh, c, 18.0f, {0.24f, 0.075f, 0.045f}, 2.04f);
    addGroundRect(mesh, c, {3.8f, 3.2f}, {0.13f, 0.13f, 0.12f}, 0.18f, 0.0f);
    addCylinder(mesh, {c.x, c.y, z + 0.10f}, 1.55f, 3.8f, 16, red);
    addEllipsoid(mesh, {c.x, c.y, z + 4.36f}, {1.45f, 1.45f, 0.78f}, red * 1.05f, 5, 12, 0.0f);
    const glm::vec3 nozzle = {c.x, c.y, z + 4.72f};
    const glm::vec3 barrelEnd = nozzle + aim * 6.8f + glm::vec3{0.0f, 0.0f, 0.76f};
    addPipeSegment(mesh, nozzle, barrelEnd, 0.32f, dark);
    addCylinder(mesh, barrelEnd - aim * 0.18f, 0.46f, 0.42f, 12, red * 1.16f);
    addDirectionalArrow(mesh, barrelEnd, glm::vec3{aim2.x, aim2.y, 0.20f}, 13.0f, water * 1.15f, 2.0f);
    addEmergencyAssetBeacon(mesh, c + glm::vec2{-aim2.y, aim2.x} * 2.9f, 11.4f, red);

    const glm::vec3 target = {
        target2.x + wind.x * windDrift, target2.y + wind.y * windDrift, groundZ(target2.x, target2.y, 3.2f)};
    addWaterArc(mesh, barrelEnd, target, 17.5f, 0.085f, water * 1.12f, 8);
  }

  void addMaxEmergencyFireTowerProxy(Mesh& mesh, glm::vec2 c, glm::vec3 sunDir) {
    const float z = groundZ(c.x, c.y, 0.0f);
    const glm::vec3 steel = {0.24f, 0.27f, 0.27f};
    const glm::vec3 red = {0.60f, 0.060f, 0.035f};
    const glm::vec3 beacon = {0.95f, 0.36f, 0.16f};
    const float h = 24.0f;
    const float foot = 2.7f;
    const std::array<glm::vec2, 4> legs = {
        c + glm::vec2{-foot, -foot},
        c + glm::vec2{foot, -foot},
        c + glm::vec2{foot, foot},
        c + glm::vec2{-foot, foot},
    };

    addEquipmentShadow(mesh, c, {5.4f, 5.4f}, h, sunDir, 0.24f);
    addGroundRect(mesh, c, {4.6f, 4.6f}, {0.10f, 0.115f, 0.115f}, 0.14f, 0.0f);
    for (glm::vec2 leg : legs) {
      addPipeSegment(mesh,
                     {leg.x, leg.y, z + 0.2f},
                     {c.x + (leg.x - c.x) * 0.52f, c.y + (leg.y - c.y) * 0.52f, z + h},
                     0.16f,
                     steel);
    }
    for (size_t i = 0; i < legs.size(); ++i) {
      const glm::vec2 a = legs[i];
      const glm::vec2 b = legs[(i + 1) % legs.size()];
      addPipeSegment(mesh, {a.x, a.y, z + 8.0f}, {b.x, b.y, z + 13.2f}, 0.075f, steel * 1.12f);
      addPipeSegment(mesh, {a.x, a.y, z + 16.0f}, {b.x, b.y, z + 21.0f}, 0.075f, steel * 0.92f);
    }
    addBox(mesh, {c.x, c.y, z + h + 0.18f}, {4.2f, 4.2f, 0.20f}, steel * 0.72f);
    addPipeSegment(mesh, {c.x - 3.6f, c.y, z + h + 1.2f}, {c.x + 3.6f, c.y, z + h + 1.2f}, 0.08f, red);
    addPipeSegment(mesh, {c.x, c.y - 3.6f, z + h + 1.2f}, {c.x, c.y + 3.6f, z + h + 1.2f}, 0.08f, red);
    addCylinder(mesh, {c.x, c.y, z + h + 0.2f}, 0.44f, 2.2f, 12, red);
    addEllipsoid(mesh, {c.x, c.y, z + h + 3.1f}, {1.1f, 1.1f, 0.68f}, beacon, 5, 12, 2.0f);
  }

