    const glm::vec2 dir = {std::cos(angle), std::sin(angle)};
    const glm::vec2 side = {-dir.y, dir.x};
    const auto point = [&](float along, float lateral, float zoff) {
      const glm::vec2 p = c + dir * along + side * lateral;
      return glm::vec3{p.x, p.y, groundZ(p.x, p.y, zoff)};
    };
    const glm::vec3 cab = index % 2 == 0 ? glm::vec3{0.82f, 0.78f, 0.58f} : glm::vec3{0.40f, 0.52f, 0.58f};
    const glm::vec3 glass = {0.035f, 0.090f, 0.112f};
    const glm::vec3 tire = {0.026f, 0.028f, 0.026f};
    const glm::vec3 hub = {0.36f, 0.37f, 0.34f};
