  void ShowcaseInteractiveApp::printControls() const {
    if (cli_.landscapeEditor) {
      std::cout << "XNBY Zhumadian Landscape Editor | point / line / region / layers\n";
      return;
    }
    std::cout << "\n=== 信能本源综合展示控制 ===\n"
              << "鼠标右键拖动     环视观察\n"
              << "鼠标左键拖动     沿地面平移\n"
              << "W/A/S/D          前后左右移动\n"
              << "Q/E              下降/上升\n"
              << "Shift            加速移动；配合 R/N/F/C/P/L 为降低参数\n"
              << "O/I/V/T/B/1-9/0  Process/Sprinkler/Routes/Drill/Performance + "
                 "总览/地景/模型/光照/粒子/天气/Warehouse/Safety/GIS/拆解\n"
              << "方向键           调整太阳方位角/高度角\n"
              << "L                循环点光源数量\n"
              << "Z/X              调整风向\n"
              << "[/]              调整风速\n"
              << "R                雨量\n"
              << "N                雪量\n"
              << "F                雾密度\n"
              << "C                云量\n"
              << "P                粒子强度\n"
              << "F8               驻马店总览/斜视/近景切换\n"
              << "G                惠炼 approach 视图中重播地球到园区飞行\n"
              << "Home             重置当前预设相机\n"
              << "Esc              退出\n";
  }

  bool ShowcaseInteractiveApp::initialize() {
    if (cli_.landscapeEditor) {
      editorFile_ =
          cli_.landscapeLayers.empty() ? resolveProjectPath("projects") / L"驻马店图层.json" : cli_.landscapeLayers;
      if (fs::exists(editorFile_))
        editorDocument_ = hongtu::landscape::load(editorFile_);
      if (editorDocument_["layers"].empty())
        editorDocument_ = hongtu::landscape::emptyDocument();
    }
    windowWidth_ = cli_.width;
    windowHeight_ = cli_.height;
    sceneConfig_ = loadSceneConfig(cli_);
    settings_ =
        applyCliOverrides(cli_, applyXinengMaxCatalogCameraFocus(cli_, settingsForPreset(cli_.preset, sceneConfig_)));
    gisMeasureMode_ = cli_.gisMeasureMode;
    routePlanMode_ = cli_.routePlanMode;
    processAnalysisMode_ = cli_.processAnalysisMode;
    sprinklerMode_ = cli_.sprinklerMode;
    fountainMode_ = cli_.fountainMode;
    gasDiffusionMode_ = cli_.gasDiffusionMode;
    disassemblyStepMode_ = cli_.disassemblyStepMode;
    materialInspectionMode_ = cli_.materialInspectionMode;
    xinengMaxCatalogMode_ = cli_.xinengMaxCatalogMode;
    drillScenarioTime_ = clampFloat(cli_.hasScenarioTime ? cli_.scenarioTimeSeconds : 0.0f,
                                    0.0f,
                                    static_cast<float>(kEmergencyDrillDurationSeconds));
    drillPlaybackStageIndex_ = drillPlaybackStageForTime(drillScenarioTime_);
    if (cli_.preset == Preset::Huilian && cli_.huilianView == "approach") {
      huilianApproachProgress_ =
          cli_.hasHuilianApproachProgress ? glm::clamp(cli_.huilianApproachProgress, 0.0f, 1.0f) : 0.0f;
      huilianApproachPlaying_ = !cli_.hasHuilianApproachProgress;
      huilianApproachStartSeconds_ = 0.0f;
    }
    applyCameraPreset();
    if (!initWindow())
      return false;
    if (!initControlPanel())
      return false;
    if (!initVulkan())
      return false;
    if (!compileShaders(device_, vertexShader_, fragmentShader_, false, false, cli_.meshSunShadows) ||
        !createMaterialTexture() || !createDepth() || !createRenderPass() || !createApproachGlobe() ||
        !createFramebuffers() || !createPipelines() || !createSync() || !rebuildScene()) {
      shutdown();
      return false;
    }
    printControls();
    if (cli_.landscapeEditor &&
        !editorOverlay_.initialize(device_, renderPass_, resolveProjectPath("assets/landscape/icons.png")))
      return false;
    return true;
  }

  bool ShowcaseInteractiveApp::initWindow() {
    if (cli_.landscapeEditor)
      return initEditorWindow();
    hinstance_ = GetModuleHandleW(nullptr);
    WNDCLASSW wc{};
    wc.lpfnWndProc = ShowcaseInteractiveApp::windowProc;
    wc.hInstance = hinstance_;
    wc.lpszClassName = L"XinengBenyuanShowcaseDemoWindow";
    wc.hCursor = LoadCursor(nullptr, IDC_ARROW);
    wc.hbrBackground = reinterpret_cast<HBRUSH>(COLOR_WINDOW + 1);
    RegisterClassW(&wc);

    DWORD style = WS_OVERLAPPEDWINDOW;
    int posX = CW_USEDEFAULT;
    int posY = CW_USEDEFAULT;
    if (cli_.fullscreen) {
      MONITORINFO monitorInfo{};
      monitorInfo.cbSize = sizeof(MONITORINFO);
      if (GetMonitorInfoW(MonitorFromWindow(nullptr, MONITOR_DEFAULTTOPRIMARY), &monitorInfo)) {
        posX = monitorInfo.rcMonitor.left;
        posY = monitorInfo.rcMonitor.top;
        windowWidth_ = monitorInfo.rcMonitor.right - monitorInfo.rcMonitor.left;
        windowHeight_ = monitorInfo.rcMonitor.bottom - monitorInfo.rcMonitor.top;
        style = WS_POPUP;
        fullscreen_ = true;
      }
    }

    RECT rect{0, 0, windowWidth_, windowHeight_};
    if (!fullscreen_)
      AdjustWindowRect(&rect, style, FALSE);
    hwnd_ = CreateWindowExW(0,
                            wc.lpszClassName,
                            L"信能本源 - 工业园区三维展示",
                            style | WS_VISIBLE,
                            posX,
                            posY,
                            rect.right - rect.left,
                            rect.bottom - rect.top,
                            nullptr,
                            nullptr,
                            hinstance_,
                            this);
    if (!hwnd_) {
      std::cerr << "CreateWindowExW failed\n";
      return false;
    }
    ShowWindow(hwnd_, fullscreen_ ? SW_SHOW : SW_MAXIMIZE);
    UpdateWindow(hwnd_);
    RECT client{};
    if (GetClientRect(hwnd_, &client)) {
      windowWidth_ = std::max(1L, client.right - client.left);
      windowHeight_ = std::max(1L, client.bottom - client.top);
    }
    return true;
  }

