  bool parsePreset(const std::string& value, Preset& out) {
    if (value == "overview")
      out = Preset::Overview;
    else if (value == "terrain")
      out = Preset::Terrain;
    else if (value == "fusion")
      out = Preset::Fusion;
    else if (value == "gis")
      out = Preset::Gis;
    else if (value == "models")
      out = Preset::Models;
    else if (value == "huilian")
      out = Preset::Huilian;
    else if (value == "zhumadian")
      out = Preset::Zhumadian;
    else if (value == "materials")
      out = Preset::Materials;
    else if (value == "process")
      out = Preset::Process;
    else if (value == "disassembly")
      out = Preset::Disassembly;
    else if (value == "lighting")
      out = Preset::Lighting;
    else if (value == "particles")
      out = Preset::Particles;
    else if (value == "weather")
      out = Preset::Weather;
    else if (value == "safety")
      out = Preset::Safety;
    else if (value == "sprinkler")
      out = Preset::Sprinkler;
    else if (value == "routes")
      out = Preset::Routes;
    else if (value == "warehouse")
      out = Preset::Warehouse;
    else if (value == "drill")
      out = Preset::Drill;
    else if (value == "performance")
      out = Preset::Performance;
    else
      return false;
    return true;
  }

